class Solution { public int[] maxPoints(int[][] grid,int[] queries){int rows=grid.length,cols=grid[0].length;Integer[] order=new Integer[queries.length];for(int i=0;i<queries.length;i++)order[i]=i;Arrays.sort(order,Comparator.comparingInt(i->queries[i]));PriorityQueue<int[]> heap=new PriorityQueue<>(Comparator.comparingInt(cell->cell[0]));boolean[][] visited=new boolean[rows][cols];heap.offer(new int[]{grid[0][0],0,0});visited[0][0]=true;int[] answer=new int[queries.length];int count=0;int[][] directions={{1,0},{-1,0},{0,1},{0,-1}};for(int index:order){while(!heap.isEmpty()&&heap.peek()[0]<queries[index]){int[] cell=heap.poll();count++;for(int[] direction:directions){int row=cell[1]+direction[0],col=cell[2]+direction[1];if(row>=0&&row<rows&&col>=0&&col<cols&&!visited[row][col]){visited[row][col]=true;heap.offer(new int[]{grid[row][col],row,col});}}}answer[index]=count;}return answer;} }
